/ [셋업] POS별 문항 풀에서 랜덤 인덱스(*_IDX) 추출
@SET(N_IDX, "@INDEX("@N_SEN@", "@N_SEN[.]@")@", SELF)@
@SET(V_IDX, "@INDEX("@V_SEN@", "@V_SEN[.]@")@", SELF)@
@SET(ADJ_IDX, "@INDEX("@ADJ_SEN@", "@ADJ_SEN[.]@")@", SELF)@
@SET(OTH_IDX, "@INDEX("@OTH_SEN@", "@OTH_SEN[.]@")@", SELF)@

// [셋업] 추출한 문항·정답(·보기)을 JSON_test_config에 기록
@UPJ(JSON_test_config.Noun[@R_i@].problem, "@EVAL(@R_i@)@. 다음 중 밑줄에 들어가기에 가장 적절한 단어는?<br>@N_SEN[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].answer, "@N_ANS[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].distractor, "@D("@N_ANS[@N_IDX@]@", "", "@N_DSTR@", 4)@")@
@UPJ(JSON_test_config.Noun[@R_i@].definition, "@N_DEF[@N_IDX@]@")@

@UPJ(JSON_test_config.Verb[@R_i@].problem, "@EVAL(@R_i@)@. 다음 중 밑줄에 들어가기에 가장 적절한 단어는?<br>@V_SEN[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].answer, "@V_ANS[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].distractor, "@D("@V_ANS[@V_IDX@]@", "", "@V_DSTR@", 4)@")@
@UPJ(JSON_test_config.Verb[@R_i@].definition, "@V_DEF[@V_IDX@]@")@

@UPJ(JSON_test_config.Adjective[@R_i@].problem, "@EVAL(@R_i@)@. 다음 중 밑줄에 들어가기에 가장 적절한 단어는?<br>@ADJ_SEN[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].answer, "@ADJ_ANS[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].distractor, "@D("@ADJ_ANS[@ADJ_IDX@]@", "", "@ADJ_DSTR@", 4)@")@
@UPJ(JSON_test_config.Adjective[@R_i@].definition, "@ADJ_DEF[@ADJ_IDX@]@")@

@UPJ(JSON_test_config.others[@R_i@].problem, "@EVAL(@R_i@)@. 다음 중 밑줄에 들어가기에 가장 적절한 단어는?<br>@OTH_SEN[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].answer, "@OTH_ANS[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].distractor, "@D("@OTH_ANS[@OTH_IDX@]@", "", "@OTH_DSTR@", 4)@")@
@UPJ(JSON_test_config.others[@R_i@].definition, "@OTH_DEF[@OTH_IDX@]@")@

// [채점] 학생 응답 정오 판정 후 점수·correctness 기록 (EXACT: 정확 일치)

1. Noun
T/F boolean: @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].Noun@

Enumerated: @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@

